 Border Card(UIElement content){return new Border{CornerRadius=new CornerRadius(8),Background=Theme.Surface,BorderBrush=Theme.Line,BorderThickness=new Thickness(1),Padding=new Thickness(16),Margin=new Thickness(0,0,0,16),Child=content};}
 TextBox DateField(Grid grid,int column,string label){var stack=new StackPanel{Margin=new Thickness(column==0?0:10,0,column==0?10:0,0)};stack.Children.Add(Theme.Text(label,12,Theme.Muted));var field=new TextBox{FontFamily=Theme.Mono,FontSize=13,Margin=new Thickness(0,8,0,0),ToolTip="yyyy-MM-dd HH:mm:ss，例如 2026-10-20 09:30:00"};stack.Children.Add(field);Grid.SetColumn(stack,column);grid.Children.Add(stack);return field;}
 public void SetRange(DateTime from,DateTime to,bool load){start.Text=(from.Kind==DateTimeKind.Utc?from.ToLocalTime():from).ToString("yyyy-MM-dd HH:mm:ss");end.Text=(to.Kind==DateTimeKind.Utc?to.ToLocalTime():to).ToString("yyyy-MM-dd HH:mm:ss");if(load)QueryNow();}
 bool ParseRange(out DateTime from,out DateTime to){bool a=DateTime.TryParseExact(start.Text.Trim(),"yyyy-MM-dd HH:mm:ss",CultureInfo.InvariantCulture,DateTimeStyles.None,out from);bool b=DateTime.TryParseExact(end.Text.Trim(),"yyyy-MM-dd HH:mm:ss",CultureInfo.InvariantCulture,DateTimeStyles.None,out to);if(!a||!b){status.Text="请输入 yyyy-MM-dd HH:mm:ss 格式的完整时间。";return false;}if(TimeZoneInfo.Local.IsInvalidTime(from)||TimeZoneInfo.Local.IsInvalidTime(to)){status.Text="时间处于夏令时跳过的时段，请选择有效时间。";return false;}if(TimeZoneInfo.Local.IsAmbiguousTime(from)||TimeZoneInfo.Local.IsAmbiguousTime(to)){status.Text="时间处于夏令时重复的时段，请选择不重复的边界时间。";return false;}if(to<=from){status.Text="结束时间必须晚于开始时间。";return false;}from=DateTime.SpecifyKind(from,DateTimeKind.Local);to=DateTime.SpecifyKind(to,DateTimeKind.Local);return true;}
