 public void QueryNow(){if(disposed)return;DateTime from,to;if(!ParseRange(out from,out to))return;if(cancellation!=null)cancellation.Cancel();cancellation=new CancellationTokenSource();var token=cancellation.Token;int request=++version;selectionVersion++;debounce.Stop();result=null;current=null;detail.Children.Clear();processDetail.Children.Clear();query.IsEnabled=false;csv.IsEnabled=backup.IsEnabled=timeline.IsEnabled=false;chart.HoverPoints=new List<ArchivePoint>();chart.ClearHover();chart.Data=new List<ArchiveDot>();chart.From=from.ToUniversalTime().Ticks;chart.To=to.ToUniversalTime().Ticks;chart.Selected=0;chart.InvalidateVisual();summary.Text="查询中…";selection.Text="等待查询结果";status.Text="正在读取磁盘存档…";string source=external;
 Task.Run(()=>{var data=store.Query(server,from,to,token,source);var lines=new Dictionary<string,List<ArchiveDot>>();foreach(string name in new[]{"CPU","GPU","内存"})lines[name]=data.Plot(name);foreach(string id in data.Points.SelectMany(p=>p.GpuIds??new string[0]).Distinct()){string name="GPU "+id;lines[name]=data.Plot(name);}return Tuple.Create(data,lines);},token).ContinueWith(task=>{if(Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke((Action)(()=>{if(disposed||request!=version)return;query.IsEnabled=true;if(task.IsCanceled)return;if(task.IsFaulted){status.Text="查询失败："+task.Exception.GetBaseException().Message;summary.Text="查询未完成";return;}SetResult(task.Result.Item1,task.Result.Item2);}));});
 }
 public void SetResult(ArchiveResult data,Dictionary<string,List<ArchiveDot>> lines=null){result=data;plots=lines??new Dictionary<string,List<ArchiveDot>>();if(lines==null){foreach(string name in new[]{"CPU","GPU","内存"})plots[name]=data.Plot(name);foreach(string id in data.Points.SelectMany(p=>p.GpuIds??new string[0]).Distinct()){string name="GPU "+id;plots[name]=data.Plot(name);}}string selected=CurrentMetric;metric.ItemsSource=plots.Keys.ToArray();metric.SelectedItem=plots.ContainsKey(selected)?selected:"CPU";scope.Visibility=Visibility.Visible;scope.Text=(external==null?"设备存档：":"外部存档：")+data.Header.Name+" · "+data.Header.Host;int failures=data.Points.Count(x=>!string.IsNullOrEmpty(x.Error));status.Text=data.Points.Count==0?"该范围没有记录。只能查询软件运行并完成采样后的数据。":data.Points.Count+" 条采样 · "+failures+" 条采集异常 · "+data.Skipped+" 条损坏或不可读记录已跳过\n实际记录："+LocalTime(data.Points[0].T)+" ～ "+LocalTime(data.Points[data.Points.Count-1].T);timeline.IsEnabled=csv.IsEnabled=backup.IsEnabled=data.Points.Count>0;UpdatePlot();UpdateStorage();if(data.Points.Count>0)SelectTime(data.Points[data.Points.Count-1].T);}
 public void SetMetric(string name){metric.SelectedItem=name;}
 void UpdatePlot(){if(chart==null||result==null||plots==null||!plots.ContainsKey(CurrentMetric))return;chart.HoverPoints=result.Points;chart.Metric=CurrentMetric;chart.ClearHover();chart.From=result.From;chart.To=result.To;chart.Data=plots[CurrentMetric];chart.HasGpu=!CurrentMetric.StartsWith("GPU")||result.Points.Any(x=>!double.IsNaN(x.Value(CurrentMetric)));chart.InvalidateVisual();var values=result.Points.Where(x=>string.IsNullOrEmpty(x.Error)).Select(x=>x.Value(CurrentMetric)).Where(x=>!double.IsNaN(x)).ToArray();summary.Text=values.Length==0?"没有有效数据":"最低 "+values.Min().ToString("0.0")+"%  /  平均 "+values.Average().ToString("0.0")+"%  /  最高 "+values.Max().ToString("0.0")+"%";}
 public void SelectTime(long ticks){if(result==null||result.Points.Count==0)return;int lo=0,hi=result.Points.Count-1;while(lo<hi){int mid=(lo+hi)/2;if(result.Points[mid].T<ticks)lo=mid+1;else hi=mid;}if(lo>0&&Math.Abs(result.Points[lo-1].T-ticks)<=Math.Abs(result.Points[lo].T-ticks))lo--;current=result.Points[lo];SnapshotLoading=true;DisplayedRecord=null;DisplayedProcessCount=0;chart.Selected=current.T;settingSlider=true;timeline.Value=Math.Max(0,Math.Min(1000,(current.T-result.From)*1000.0/Math.Max(1,result.To-result.From)));settingSlider=false;selection.Text="选中采样："+LocalTime(current.T)+(Math.Abs(current.T-ticks)>TimeSpan.FromSeconds(Math.Max(current.Interval*3,15)).Ticks?" · 目标时间未采集，显示最近记录":"")+(string.IsNullOrEmpty(current.Error)?"":" · 采集异常");selectionVersion++;debounce.Stop();debounce.Start();}
 void LoadSnapshot(){if(current==null)return;SnapshotLoading=true;detail.Children.Clear();processDetail.Children.Clear();detail.Children.Add(Theme.Text("正在读取选中时刻的硬件与进程快照…",12,Theme.Muted));var point=current;int ticket=selectionVersion;Task.Run(()=>store.Read(point)).ContinueWith(task=>{if(Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke((Action)(()=>{if(disposed||ticket!=selectionVersion)return;if(task.IsFaulted){SnapshotLoading=false;DisplayedRecord=null;detail.Children.Clear();processDetail.Children.Clear();detail.Children.Add(Theme.Text("快照不可读取，请重新查询。",13,Theme.Red));return;}ShowRecord(task.Result);}));});}
 public void ShowRecord(ArchiveRecord record){SnapshotLoading=false;DisplayedRecord=record;DisplayedProcessCount=0;detail.Children.Clear();processDetail.Children.Clear();var m=record.Metrics();var content=new StackPanel();var title=Theme.Text("历史快照 · "+LocalTime(record.T),17,Theme.Ink,false,true);title.TextWrapping=TextWrapping.Wrap;content.Children.Add(title);if(!string.IsNullOrEmpty(record.Error)){var error=Theme.Text("当时采集失败："+record.Error,13,Theme.Red);error.TextWrapping=TextWrapping.Wrap;error.Margin=new Thickness(0,16,0,0);content.Children.Add(error);detail.Children.Add(Card(content));return;}
 var values=Theme.Text("CPU "+m.Cpu+" · "+m.CpuCores.Count+" 个逻辑处理器 · 内存 "+ResourceSample.MemoryLabel(m.Mem),13,Theme.Muted);values.TextWrapping=TextWrapping.Wrap;values.Margin=new Thickness(0,14,0,16);content.Children.Add(values);if(m.Gpus.Count==0)content.Children.Add(Theme.Text("当时未检测到 NVIDIA GPU",13,Theme.Muted));else{content.Children.Add(GpuRow(null));foreach(var gpu in m.Gpus)content.Children.Add(GpuRow(gpu));}if(m.CpuCores.Count>0){var cores=new WrapPanel{Visibility=Visibility.Collapsed,Margin=new Thickness(0,12,0,0)};var toggle=Theme.Button("展开逐核快照",()=>{if(cores.Children.Count==0)foreach(var core in m.CpuCores){var cell=new StackPanel();cell.Children.Add(Theme.Text("CPU "+core.Index,11,Theme.Muted,true));var value=Theme.Text(core.Util.ToString("0.0")+"%",17,core.Util>=85?Theme.Amber:Theme.Green,true);value.Margin=new Thickness(0,8,0,0);cell.Children.Add(value);cores.Children.Add(new Border{Width=100,Padding=new Thickness(10),Margin=new Thickness(0,0,10,10),Background=Theme.Raised,Child=cell});}cores.Visibility=cores.Visibility==Visibility.Visible?Visibility.Collapsed:Visibility.Visible;});toggle.HorizontalAlignment=HorizontalAlignment.Left;toggle.Margin=new Thickness(0,16,0,0);content.Children.Add(toggle);content.Children.Add(cores);}detail.Children.Add(Card(content));var snapshot=new StackPanel();var processTitle=Theme.Text("进程采样时刻："+LocalTime(record.T)+" · "+server.Name,13,Theme.Teal,false,true);processTitle.TextWrapping=TextWrapping.Wrap;processTitle.Margin=new Thickness(0,16,0,8);snapshot.Children.Add(processTitle);if(record.Processes==null){var absent=Theme.Text("这条旧记录未保存进程明细，无法还原当时的进程。",13,Theme.Muted);absent.TextWrapping=TextWrapping.Wrap;snapshot.Children.Add(absent);}else{string selectedGpu=CurrentMetric.StartsWith("GPU ")?CurrentMetric.Substring(4):null;var processMetrics=new Metrics{Cpu=m.Cpu,Cores=m.Cores,Mem=m.Mem,Disk=m.Disk,Hardware=m.Hardware,Gpus=m.Gpus,Processes=selectedGpu==null?m.Processes:m.Processes.Where(p=>p.Gpu==selectedGpu).ToList()};DisplayedProcessCount=processMetrics.Processes.Count;if(selectedGpu!=null){var filterInfo=Theme.Text("筛选 GPU "+selectedGpu+" · 切换到 GPU 总览可查看全部进程",12,Theme.Muted);filterInfo.Margin=new Thickness(0,0,0,8);snapshot.Children.Add(filterInfo);}snapshot.Children.Add(processes(processMetrics));}processDetail.Children.Add(snapshot);}
 Grid GpuRow(Gpu gpu){var grid=new Grid{Margin=new Thickness(0,0,0,8),MinHeight=32};double[] widths={58,-1,74,172,64};for(int i=0;i<widths.Length;i++)grid.ColumnDefinitions.Add(new ColumnDefinition{Width=widths[i]<0?new GridLength(1,GridUnitType.Star):new GridLength(widths[i])});string[] text=gpu==null?new[]{"GPU","型号","利用率","显存 MiB","温度"}:new[]{gpu.Index,gpu.Name,gpu.Util+"%",gpu.Used+" / "+gpu.Total,gpu.Temp+"°C"};for(int i=0;i<text.Length;i++){var t=Theme.Text(text[i],gpu==null?11:12,gpu==null?Theme.Muted:Theme.Ink,i!=1);t.ToolTip=text[i];t.Margin=new Thickness(0,6,10,6);Grid.SetColumn(t,i);grid.Children.Add(t);}return grid;}
 static string SafeName(string value){foreach(char c in Path.GetInvalidFileNameChars())value=value.Replace(c,'_');return value.Length>48?value.Substring(0,48):value;}
 void Export(bool portable){if(result==null||result.Points.Count==0)return;var data=result;var dialog=new SaveFileDialog{FileName=SafeName(server.Name)+"-"+new DateTime(data.From,DateTimeKind.Utc).ToLocalTime().ToString("yyyyMMdd-HHmm")+(portable?".aqhistory":".csv"),Filter=portable?"AQ Server 存档|*.aqhistory":"CSV 表格|*.csv",OverwritePrompt=true};if(dialog.ShowDialog(Window.GetWindow(this))!=true)return;csv.IsEnabled=backup.IsEnabled=false;status.Text="正在导出…";Task.Run(()=>{if(portable)store.ExportArchive(data,dialog.FileName,CancellationToken.None);else store.ExportCsv(data,dialog.FileName);}).ContinueWith(task=>{if(Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke((Action)(()=>{if(disposed)return;csv.IsEnabled=backup.IsEnabled=result!=null&&result.Points.Count>0;status.Text=task.IsFaulted?"导出失败："+task.Exception.GetBaseException().Message:"已导出："+dialog.FileName;}));});}
 void OpenArchive(){var dialog=new OpenFileDialog{Filter="AQ Server 存档|*.aqhistory",CheckFileExists=true};if(dialog.ShowDialog(Window.GetWindow(this))!=true)return;try{var header=store.ReadHeader(dialog.FileName);external=dialog.FileName;DateTime from=header.Start>0?new DateTime(header.Start,DateTimeKind.Utc).ToLocalTime():DateTime.Now.AddDays(-1);DateTime to=header.End>header.Start?new DateTime(header.End,DateTimeKind.Utc).ToLocalTime():DateTime.Now;SetRange(from,to,true);}catch(Exception e){status.Text="无法打开存档："+e.Message;}}
 void OpenFolder(){try{Directory.CreateDirectory(store.Folder(server));System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(store.Folder(server)){UseShellExecute=true});}catch(Exception e){status.Text=e.Message;}}
 public void UpdateStorage(){if(storage==null)return;try{var info=store.Info(server);string size=info.Bytes<1048576?(info.Bytes/1024.0).ToString("0.0")+" KiB":(info.Bytes/1048576.0).ToString("0.0")+" MiB";storage.Text=(writerStatus==null?"本地存档":writerStatus())+" · 当前设备 "+size+" · "+info.Files+" 个存档分片 · 保留上限 "+store.Days+" 天 / 全部设备 "+store.LimitMB+" MiB · 自动清理最早存档\n显示时区："+TimeZoneInfo.Local.DisplayName;}catch(Exception e){storage.Text="存档状态："+e.Message;}}
 public static string LocalTime(long ticks){return new DateTime(ticks,DateTimeKind.Utc).ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss");}
 public void Dispose(){disposed=true;version++;selectionVersion++;if(cancellation!=null)cancellation.Cancel();if(debounce!=null)debounce.Stop();}
